# Configuration file for the Sphinx documentation builder.
#
# This build documents the source tree it is checked out alongside: the API
# reference is generated by sphinx-autoapi from ../flystar by static analysis,
# so the package does NOT need to be importable (and its runtime dependencies
# do not need to be installed) for the docs to build.

import os
import sys
import datetime

if sys.version_info >= (3, 11):
    import tomllib
else:
    import tomli as tomllib

# -- Project information ------------------------------------------------------

# Metadata comes from pyproject.toml, which is the single source for it --
# setuptools reads [project] in preference to setup.cfg's [metadata], so the
# latter no longer exists.
with open(os.path.join(os.path.dirname(__file__), '..', 'pyproject.toml'), 'rb') as _f:
    _project = tomllib.load(_f)['project']

# The distribution is `flystar`, lower case, as pip requires; the documentation
# calls it FlyStar throughout, and this is what the sidebar's home link and the
# page titles show.
project = 'FlyStar'
author = ', '.join(a['name'] for a in _project.get('authors', [])) or 'the FlyStar authors'
copyright = '{0}, {1}'.format(datetime.datetime.now().year, author)

# The package is deliberately not imported (see above), so take the version from
# installed metadata when it happens to be available and fall back to whatever
# Read the Docs is building otherwise.
try:
    from importlib.metadata import version as _get_version
    release = _get_version(project)
except Exception:
    release = os.environ.get('READTHEDOCS_VERSION', 'dev')
version = release.split('+')[0]

# -- General configuration ----------------------------------------------------

extensions = [
    'sphinx.ext.autodoc',
    'sphinx.ext.autosummary',
    'sphinx.ext.doctest',
    'sphinx.ext.intersphinx',
    'sphinx.ext.mathjax',
    'sphinx.ext.napoleon',
    'sphinx.ext.viewcode',
    'autoapi.extension',
    'myst_nb',
]

exclude_patterns = [
    '_build',
    '**.ipynb_checkpoints',
    'Thumbs.db',
    '.DS_Store',
    # Written against the pre-mm_rework API and needs a live Gaia query.
    # Kept in the tree, excluded from the build until it is updated.
    'examples/flystar_mosaic_to_gaia/**',
    # Internal design notes, not part of the user documentation.
    'plans/**',
]

highlight_language = 'python3'
nitpicky = False

# -- Napoleon (numpydoc-style docstrings) -------------------------------------

napoleon_google_docstring = False
napoleon_numpy_docstring = True
napoleon_use_param = True
napoleon_use_rtype = True

# This codebase's docstrings use several non-standard section headings. Map each
# onto the standard section it actually means, so napoleon renders them as real
# parameter/return lists instead of leaving them as stray RST section titles.
napoleon_custom_sections = [
    ('Required Parameters', 'Parameters'),
    ('Optional Parameters', 'Parameters'),
    ('Input', 'Parameters'),
    ('Inputs', 'Parameters'),
    ('Optional Inputs', 'Parameters'),
    ('Optional Input', 'Parameters'),
    ('Outputs', 'Returns'),
    ('Optional Keywords', 'Parameters'),
    ('Required table columns (input as keywords)', 'Parameters'),
    ('Optional table columns (input as keywords)', 'Parameters'),
    ('Optional table meta data', 'Parameters'),
    ('Output', 'Returns'),
]

# -- sphinx-autoapi -----------------------------------------------------------
#
# autoapi walks the source statically, so every module on this branch is picked
# up automatically -- including ones that post-date the old hand-maintained
# automodapi list (motion_model, parallax, startables ...).

autoapi_dirs = ['../flystar']
autoapi_root = 'api'
autoapi_type = 'python'
autoapi_member_order = 'groupwise'
autoapi_options = [
    'members',
    'undoc-members',
    'show-inheritance',
    'show-module-summary',
    'imported-members',
]
autoapi_ignore = [
    '*/conftest.py',
    '*/tests/*',
    '*/_astropy_init*',
    '*/version.py',
    '*/setup_package*',
    '*/conf.py',
    '*/parallax_cache/*',
    '*/extern/*',
    '*/data/*',
]
autoapi_add_toctree_entry = False   # the toctree entry lives in index.rst
autoapi_keep_files = False
autoapi_python_class_content = 'both'

# -- myst-nb (renders the example notebooks) ---------------------------------
#
# Notebooks are rendered from their stored outputs and are never executed at
# build time: executing them would require the full science stack plus the data
# files each example reads.

nb_execution_mode = 'off'
myst_heading_anchors = 4
myst_enable_extensions = ['dollarmath', 'amsmath', 'colon_fence']
suppress_warnings = ['mystnb.unknown_mime_type']

# -- Intersphinx --------------------------------------------------------------

intersphinx_mapping = {
    'python': ('https://docs.python.org/3/', None),
    'numpy': ('https://numpy.org/doc/stable/', None),
    'scipy': ('https://docs.scipy.org/doc/scipy/', None),
    'astropy': ('https://docs.astropy.org/en/stable/', None),
    'matplotlib': ('https://matplotlib.org/stable/', None),
}

# -- HTML output --------------------------------------------------------------

html_theme = 'furo'
html_title = f'{project} {version}'
html_static_path = ['_static']
templates_path = ['_templates']

# "Edit this page" and "View source" links. The repository URL comes from
# pyproject.toml, so there is one place to change it. Outside Read the Docs
# (e.g. the GitHub Pages build) the links point at dev, the branch these docs
# are built from; most of these pages do not exist on main.
github_url = _project.get('urls', {}).get(
    'repository', 'https://github.com/MovingUniverseLab/flystar'
).rstrip('/')
html_theme_options = {
    'source_repository': f'{github_url}/',
    'source_branch': os.environ.get('READTHEDOCS_GIT_IDENTIFIER', 'dev'),
    'source_directory': 'docs/',
}

# The sidebar lists each page's sections three levels deep, all expanded, as
# the previous theme did (sphinx_rtd_theme with navigation_depth=3 and
# collapse_navigation=False). furo's own sidebar lists only the page titles.
SIDEBAR_DEPTH = 3


def _sidebar_with_sections(app, pagename, templatename, context, doctree):
    """List the sections of each page in furo's sidebar, not only the page titles."""
    from furo.navigation import get_navigation_tree
    if 'toctree' in context:
        context['furo_navigation_tree'] = get_navigation_tree(
            context['toctree'](collapse=False, titles_only=False, maxdepth=SIDEBAR_DEPTH, includehidden=True))


def _param_defaults(app, what, name, obj, skip, options):
    """
    Add each argument's default value to its parameter description.

    Parameters
    ----------
    app : sphinx.application.Sphinx
        The Sphinx application.
    what : str
        autoapi object type ('class', 'function', 'method', ...).
    name : str
        Fully qualified name of the object.
    obj : autoapi PythonObject
        The parsed object; its docstring has already been through napoleon.
    skip : bool
        Whether autoapi will skip the object.
    options : list of str
        autoapi_options.

    Returns
    -------
    None
        Leaves autoapi's skip decision unchanged.

    Notes
    -----
    NumPy docstrings often mark a parameter ``optional`` without its value.
    The default is read from the signature autoapi parsed, so it cannot go
    stale. A parameter whose description already mentions a default is left
    alone.
    """
    # Classes take their arguments from the constructor.
    func = getattr(obj, 'constructor', None) if what == 'class' else obj
    if what not in ('class', 'function', 'method') or func is None:
        return None

    # Arguments that have a default: {name: default as written in the source}.
    defaults = {arg[1]: arg[3] for arg in func.obj.get('args', []) if arg[3] is not None}
    if not defaults or not obj.docstring:
        return None

    lines = obj.docstring.splitlines()
    for i, line in enumerate(lines):
        # napoleon writes each parameter's type as ':type <name>: <type text>'.
        if not line.lstrip().startswith(':type '):
            continue
        field, _, type_text = line.lstrip()[len(':type '):].partition(':')
        if field not in defaults or 'default' in type_text.lower():
            continue

        # Skip parameters whose description already states a default.
        param_text = []
        for j in range(i - 1, -1, -1):
            param_text.append(lines[j])
            if lines[j].lstrip().startswith(f':param {field}:'):
                break
        if 'default' in ' '.join(param_text).lower():
            continue

        # Replace 'optional' with the default, or append it.
        indent = line[:len(line) - len(line.lstrip())]
        type_text = type_text.strip().removesuffix('optional').rstrip(', ')
        sep = ', ' if type_text else ''
        lines[i] = f'{indent}:type {field}: {type_text}{sep}default: {defaults[field]}'

    obj.docstring = '\n'.join(lines)

    return None


def setup(app):
    """
    Connect the sidebar and parameter-default hooks.

    Parameters
    ----------
    app : sphinx.application.Sphinx
        The Sphinx application.

    Returns
    -------
    None
    """
    # Run _sidebar_with_sections after furo has set its sidebar.
    app.connect('html-page-context', _sidebar_with_sections, priority=900)

    # Fill in parameter defaults from the parsed signatures.
    app.connect('autoapi-skip-member', _param_defaults)

    return None
